// Parse Zalo OA webhook data
const body = $input.first().json.body;
const eventName = body.event_name || 'unknown';
const msg = body.message || {};
let ts = new Date();
if (msg.timestamp) {
  ts = msg.timestamp > 1e12 ? new Date(msg.timestamp) : new Date(msg.timestamp * 1000);
}
let msgType = 'text';
let msgText = '';
let mediaUrl = '';
let stickerId = '';
let lat = 0;
let lng = 0;
let addr = '';

if (eventName === 'user_send_text') { msgType = 'text'; msgText = msg.text || ''; }
else if (eventName === 'user_send_image') { msgType = 'image'; msgText = msg.text || '[Hinh anh]'; mediaUrl = msg.attachments && msg.attachments[0] && msg.attachments[0].payload ? msg.attachments[0].payload.url : ''; }
else if (eventName === 'user_send_file') { msgType = 'file'; msgText = msg.text || '[File]'; mediaUrl = msg.attachments && msg.attachments[0] && msg.attachments[0].payload ? msg.attachments[0].payload.url : ''; }
else if (eventName === 'user_send_link') { msgType = 'link'; msgText = msg.text || '[Link]'; }
else if (eventName === 'user_send_sticker') { msgType = 'sticker'; msgText = '[Sticker]'; stickerId = msg.sticker && msg.sticker.id ? msg.sticker.id : ''; }
else if (eventName === 'user_send_location') { msgType = 'location'; msgText = msg.text || '[Vi tri]'; if (msg.location && msg.location.coordinates) { lat = msg.location.coordinates.latitude || 0; lng = msg.location.coordinates.longitude || 0; } addr = msg.location && msg.location.address ? msg.location.address : ''; }
else if (eventName === 'follow') { msgType = 'system'; msgText = 'Nguoi dung da theo doi OA'; }
else if (eventName === 'unfollow') { msgType = 'system'; msgText = 'Nguoi dung da bo theo doi OA'; }
else { msgText = msg.text || JSON.stringify(msg); }

const isFromCustomer = eventName.startsWith('user_send') || eventName === 'follow' || eventName === 'unfollow';

let userId;
if (isFromCustomer) { userId = body.sender && body.sender.id ? body.sender.id : 'unknown'; }
else { userId = (body.recipient && body.recipient.id) ? body.recipient.id : ((body.sender && body.sender.id) ? body.sender.id : 'unknown'); }

return {
  json: {
    idcompany: 1,
    user_id: userId,
    zalo_message_id: msg.msg_id || '',
    message: msgText,
    message_type: msgType,
    media_url: mediaUrl,
    file_name: '',
    file_size: 0,
    link_url: '',
    link_title: '',
    link_description: '',
    link_thumb_url: '',
    sticker_id: stickerId,
    latitude: lat,
    longitude: lng,
    address: addr,
    is_from_customer: isFromCustomer ? 1 : 0,
    is_read: 0,
    timestamp: ts.toISOString(),
    created_at: new Date().toISOString(),
    user_name: '',
    user_avatar: ''
  }
};

// Lay thong tin user tu Zalo API
const userData = $input.first().json;
const userName = userData.name || 'Khach hang';
const userAvatar = userData.picture && userData.picture.data && userData.picture.data.url ? userData.picture.data.url : '';

// Lay data tu node truoc
const msgData = $('Code Parse').first().json;

return {
  json: {
    ...msgData,
    user_name: userName,
    user_avatar: userAvatar
  }
};
